Given the root of a binary tree. Return the left view of the binary tree. The left view of a binary tree is the set of nodes visible when the tree is viewed from the left side.Note: If the tree is empty, return an empty list.Examples:Input: root = [1, 2, 3, 4, 5, N, N]  Output: [1, 2, 4]Explanation: From the left side of the tree, only the nodes 1, 2, and 4 are visible. Input: root = [1, 2, 3, N, N, 4, N, N, 5, N, N] Output: [1, 2, 4, 5]Explanation: From the left side of the tree, only the nodes 1, 2, 4, and 5 are visible. Try It YourselfTable of ContentLevel Order Traversal (BFS) - O(n) Time and O(n) SpaceDFS (Preorder Traversal) - O(n) Time and O(h) SpaceLevel Order Traversal (BFS) - O(n) Time and O(n) SpaceThe idea is to traverse the tree level by level using a queue. At each level, the first node processed is the leftmost node, so we add it to the answer.Working of Approach:If the tree is empty, return an empty vector.Perform level order traversal using a queue.Process one level at a time.Store the first node of every level in the result.Continue until all levels are traversed.
            C++

    #include <iostream>
#include <queue>
#include <sstream>
#include <vector>
using namespace std;

class Node
{
  public:
    int data;
    Node *left;
    Node *right;

    Node(int val)
    {
        data = val;
        left = right = nullptr;
    }
};

vector<int> leftView(Node *root)
{

    vector<int> res;

    // If the tree is empty
    if (root == nullptr)
        return res;

    queue<Node *> q;
    q.push(root);

    // Perform level order traversal
    while (!q.empty())
    {

        int levelSize = q.size();

        for (int i = 0; i < levelSize; i++)
        {

            Node *curr = q.front();
            q.pop();

            // First node of current level is part of left view
            if (i == 0)
                res.push_back(curr->data);

            // Push left child
            if (curr->left)
                q.push(curr->left);

            // Push right child
            if (curr->right)
                q.push(curr->right);
        }
    }

    return res;
}

int main()
{

    // Tree:
    //          1
    //        /   \
    //       2     3
    //            /
    //           4
    //            \
    //             5

    Node *root = new Node(1);

    root->left = new Node(2);
    root->right = new Node(3);

    root->right->left = new Node(4);

    root->right->left->right = new Node(5);

    vector<int> ans = leftView(root);

    cout << "[";

    for (int i = 0; i < ans.size(); i++)
    {
        cout << ans[i];
        if (i != ans.size() - 1)
            cout << ", ";
    }

    cout << "]";

    return 0;
}


